        x[i] = (2.0 * M_PI) * i / 399.0;
    }

    // square = np.where(x &lt; np.pi, 1.0, -1.0)
    std::vector&lt;double&gt; square(400);
    for (int i = 0; i &lt; 400; ++i) {
        square[i] = (x[i] &lt; M_PI) ? 1.0 : -1.0;
    }

